	@ParameterizedTest
	@EnumSource(NativeCoordinatorCompletionContractTest.Stop.class)
	void actualWorkerDistinctCopyHonorsItsTerminalOwner(NativeCoordinatorCompletionContractTest.Stop stop)
			throws Exception {
		try (Fixture control = Fixture.forWorkerMerge(false, false)) {
			control.assertResult(control.run());
			assertThat(control.workerMergeReads.get()).as("actual worker DISTINCT copy hashes must execute")
					.isPositive();
			assertThat(control.closedSources).hasValue(2);
			assertThat(control.closedWithActiveKernel).isFalse();
			assertThat(control.manager.usedBytes()).isZero();
		}
		try (Fixture fixture = Fixture.forWorkerMerge(stop != NativeCoordinatorCompletionContractTest.Stop.NONE,
				stop == NativeCoordinatorCompletionContractTest.Stop.PROBE)) {
			AtomicReference<List<BindingSet>> result = new AtomicReference<>();
			Throwable failure = catchThrowable(() -> result.set(fixture.run()));
			assertThat(fixture.boundKernels.get()).as("the copy must belong to real interpreter workers").isPositive();
			assertThat(fixture.workerMergeReads.get()).isPositive();
			assertThat(fixture.closedSources).hasValue(2);
			assertThat(fixture.closedWithActiveKernel).isFalse();
			if (stop == NativeCoordinatorCompletionContractTest.Stop.NONE) {
				assertThat(failure).isNull();
				assertThat(result.get()).isInstanceOf(NativeReplayBindingList.class);
				assertThat(fixture.manager.usedBytes()).as("the returned result still owns its replay workspace")
						.isPositive();
				fixture.assertResult(result.get());
			} else {
				assertThat(fixture.signalled).as("a hash inside the actual worker merge requests termination").isTrue();
				assertThat(fixture.workerMergeReadsAfterSignal.get())
						.as("two workers must poll within a bounded DISTINCT copy, independently of set size")
						.isLessThanOrEqualTo(2 * POLL_BOUND);
				if (stop == NativeCoordinatorCompletionContractTest.Stop.QUERY) {
					assertOwnedQueryCancellation(failure, fixture.emitter.cancellation);
				} else {
					assertThat(failure).isSameAs(LmdbNativeProbeDeadlineExceeded.INSTANCE);
				}
				assertThat(result.get()).isNull();
				if (stop == NativeCoordinatorCompletionContractTest.Stop.PROBE) {
					assertThat(fixture.emitter.cancellation.isCancellationRequested()).isFalse();
				}
			}
			assertThat(fixture.manager.usedBytes()).as("all worker and consumed result ownership is released").isZero();
		}
	}

