	@Test
	void actualWorkerPhasesCarryTheirExplicitRootThreadOwner(@TempDir Path directory) throws Exception {
		long rootThread = Thread.currentThread().threadId();
		long evaluation;
		Path output = directory.resolve("worker-owner.jfr");
		try (Recording recording = new Recording()) {
			recording.enable("org.eclipse.rdf4j.lmdb.NativeExecutionPhase").withThreshold(Duration.ZERO);
			recording.start();
			try (Fixture fixture = Fixture.forWorkerMerge(false, false)) {
				evaluation = fixture.emitter.cancellation.evaluationId();
				fixture.assertResult(fixture.run());
				assertThat(fixture.workerMergeReads.get()).isPositive();
				assertThat(fixture.closedSources).hasValue(2);
				assertThat(fixture.closedWithActiveKernel).isFalse();
				assertThat(fixture.manager.usedBytes()).isZero();
			}
			recording.stop();
			recording.dump(output);
		}
		List<RecordedEvent> events = RecordingFile.readAllEvents(output)
				.stream()
				.filter(event -> event.getEventType().getName().equals("org.eclipse.rdf4j.lmdb.NativeExecutionPhase")
						&& event.getLong("evaluationId") == evaluation)
				.toList();
		assertThat(events).isNotEmpty().anyMatch(event -> event.getThread().getJavaThreadId() != rootThread);
		for (RecordedEvent event : events) {
			assertThat(event.getEventType().getField("ownerThreadId"))
					.as("every actual worker and cleanup event needs a causal root-owner identity")
					.isNotNull();
			assertThat(event.getLong("ownerThreadId")).isEqualTo(rootThread);
		}
	}

	@Test
	void detachedPhaseIdentityRetainsItsEntryThreadAcrossHandoff(@TempDir Path directory) throws Exception {
		long rootThread = Thread.currentThread().threadId();
		NativeExecutionPhaseEvent.Identity identity;
		Path output = directory.resolve("detached-owner.jfr");
		try (Recording recording = new Recording();
				Fixture fixture = Fixture.forWorkerMerge(false, false);
				ExecutorService continuation = Executors.newSingleThreadExecutor()) {
			recording.enable("org.eclipse.rdf4j.lmdb.NativeExecutionPhase").withThreshold(Duration.ZERO);
			recording.start();
			fixture.assertResult(fixture.run());
			assertThat(fixture.workerMergeReads.get()).isPositive();
			assertThat(fixture.closedSources).hasValue(2);
			assertThat(fixture.closedWithActiveKernel).isFalse();
			assertThat(fixture.manager.usedBytes()).isZero();
			NativeLmdbQuerySource input = fixture.source.delegate;
			try (NativeExecutionPhaseEvent.InputScope scope = NativeExecutionPhaseEvent.inputScope(
					fixture.emitter.cancellation)) {
				identity = NativeExecutionPhaseEvent.captureIdentity(input);
			}
			assertThat(identity.evaluationId()).isEqualTo(fixture.emitter.cancellation.evaluationId());
			continuation.submit(() -> {
				try (NativeExecutionPhaseEvent.Span span = NativeExecutionPhaseEvent.startDetached(
						"fixture-detached-handoff", identity)) {
					span.complete();
				}
			}).get();
			recording.stop();
			recording.dump(output);
		}
		List<RecordedEvent> events = RecordingFile.readAllEvents(output)
				.stream()
				.filter(event -> event.getEventType().getName().equals("org.eclipse.rdf4j.lmdb.NativeExecutionPhase")
						&& event.getString("phase").equals("fixture-detached-handoff"))
				.toList();
		assertThat(events).hasSize(1);
		assertThat(events.getFirst().getThread().getJavaThreadId()).isNotEqualTo(rootThread);
		assertThat(events.getFirst().getLong("evaluationId")).isEqualTo(identity.evaluationId());
		assertThat(events.getFirst().getLong("ownerThreadId"))
				.as("a detached continuation must retain the captured evaluation entry, not its later binding thread")
				.isEqualTo(rootThread);
	}

